"id":"db-2-15","category":"database_technical","subcategory":"Subqueries","question_text":"What must a scalar subquery return?","options":["Exactly four columns","Only Boolean values","At most one row and one column","An entire table"],"correct_answer":"C","explanation":"A scalar context expects a single value.","estimated_time_seconds":60,"difficulty":2,"option_a":"Exactly four columns","option_b":"Only Boolean values","option_c":"At most one row and one column","option_d":"An entire table"},{"id":"db-2-16","category":"database_technical","subcategory":"Constraints","question_text":"Which constraint prevents duplicate values in a column or column set?","options":["DEFAULT","CHECK","NOT NULL only","UNIQUE"],"correct_answer":"D","explanation":"UNIQUE enforces distinct non-null key combinations according to database semantics.","estimated_time_seconds":60,"difficulty":2,"option_a":"DEFAULT","option_b":"CHECK","option_c":"NOT NULL only","option_d":"UNIQUE"},{"id":"db-2-17","category":"database_technical","subcategory":"Constraints","question_text":"What does NOT NULL enforce?","options":["A column must contain a value for every row","A column must be unique","A table cannot be deleted","A query cannot return zero rows"],"correct_answer":"A","explanation":"NOT NULL rejects rows that omit a value for that column.","estimated_time_seconds":60,"difficulty":2,"option_a":"A column must contain a value for every row","option_b":"A column must be unique","option_c":"A table cannot be deleted","option_d":"A query cannot return zero rows"},{"id":"db-2-18","category":"database_technical","subcategory":"Views","question_text":"How does a materialized view differ from a standard view?","options":["It cannot contain a SELECT query","It stores query results that must be refreshed","It always updates each second","It bypasses every permission"],"correct_answer":"B","explanation":"A materialized view persists results instead of only storing a query definition.","estimated_time_seconds"